import java.io.*;
import java.util.*;

public class C {

	BufferedReader bufReader;
	PrintWriter printWriter;
	StringTokenizer tokenStream;
	boolean eofFlag;

	void run() throws IOException {
		nextInt();
		String s = nextToken();
		printWriter.println(fast(s));
	}

	static final String BAD_CHARS = "VK";

	String sanitize(String s) {
		StringBuilder sb = new StringBuilder();
		for (char c : s.toCharArray()) {
			if (BAD_CHARS.indexOf(c) >= 0) {
				sb.append(c);
			} else {
				sb.append('A');
			}
		}
		return sb.toString();
	}

	int slowMethod(String s) {
		s = sanitize(s);
		Map<String, Integer> visitedMap = new HashMap<>();
		ArrayDeque<String> queue = new ArrayDeque<>();
		queue.add(s);
		visitedMap.put(s, 0);

		while (true) {
			String currentStr = queue.poll();
			int dist = visitedMap.get(currentStr);
			if (currentStr.indexOf(BAD_CHARS) == -1) {
				return dist;
			}
			for (int i = 0; i < currentStr.length() - 1; i++) {
				String swapped = swapChars(currentStr, i, i + 1);
				if (swapped != null && !visitedMap.containsKey(swapped)) {
					visitedMap.put(swapped, dist + 1);
					queue.add(swapped);
				}
			}
		}
	}

	String swapChars(String s, int i, int j) {
		if (s.charAt(i) == s.charAt(j)) return null;
		char[] arr = s.toCharArray();
		char tmp = arr[i];
		arr[i] = arr[j];
		arr[j] = tmp;
		return new String(arr);
	}

	static final String TARGET_SEQ = "VKA";

	int fast(String s) {
		s = sanitize(s);
		int len = s.length();
		int[] indices = new int[len];
		int[][] positions = new int[3][len];
		int[] sizes = new int[3];

		int[][][] countHere = new int[3][len][3];

		int[][] prefixSum = new int[len + 1][];
		prefixSum[0] = new int[] {0, 0, 0};

		for (int i = 0; i < len; i++) {
			indices[i] = TARGET_SEQ.indexOf(s.charAt(i));
			int cIdx = indices[i];
			countHere[cIdx][sizes[cIdx]] = prefixSum[i].clone();
			positions[cIdx][sizes[cIdx]] = i;
			sizes[cIdx]++;
			prefixSum[i + 1] = prefixSum[i].clone();
			prefixSum[i + 1][cIdx]++;
		}

		int[][][][] dp = new int[2][sizes[0] + 1][sizes[1] + 1][sizes[2] + 1];

		for (int i = 0; i < 2; i++) {
			for (int j0 = 0; j0 <= sizes[0]; j0++) {
				for (int j1 = 0; j1 <= sizes[1]; j1++) {
					Arrays.fill(dp[i][j0][j1], INF);
				}
			}
		}

		int minCost = INF;
		dp[0][0][0][0] = 0;

		for (int j0 = 0; j0 <= sizes[0]; j0++) {
			for (int j1 = 0; j1 <= sizes[1]; j1++) {
				for (int j2 = 0; j2 <= sizes[2]; j2++) {
					for (int last = 0; last < 2; last++) {
						int totalIdx = j0 + j1 + j2;
						int current = dp[last][j0][j1][j2];
						if (current == INF) continue;
						if (totalIdx == len) {
							minCost = Math.min(minCost, current);
							continue;
						}
						if (j0 < sizes[0]) {
							int cost = Math.max(j1 - countHere[0][j0][1], 0)
									+ Math.max(j2 - countHere[0][j0][2], 0);
							dp[1][j0 + 1][j1][j2] = Math.min(dp[1][j0 + 1][j1][j2], current + cost);
						}
						if (j1 < sizes[1] && last == 0) {
							int cost = Math.max(j0 - countHere[1][j1][0], 0)
									+ Math.max(j2 - countHere[1][j1][2], 0);
							dp[0][j0][j1 + 1][j2] = Math.min(dp[0][j0][j1 + 1][j2], current + cost);
						}
						if (j2 < sizes[2]) {
							int cost = Math.max(j0 - countHere[2][j2][0], 0)
									+ Math.max(j1 - countHere[2][j2][1], 0);
							dp[0][j0][j1][j2 + 1] = Math.min(dp[0][j0][j1][j2 + 1], current + cost);
						}
					}
				}
			}
		}
		return minCost;
	}

	static final int INF = 1_000_000;

	String generateSampleString() {
		Random rand = new Random(321);
		int n = 7;
		char[] buf = new char[n];
		for (int i = 0; i < n; i++) {
			buf[i] = TARGET_SEQ.charAt(rand.nextInt(3));
		}
		return new String(buf);
	}

	void run() {
		Random rand = new Random(321);
		for (int t = 0;; t++) {
			String s = generateSampleString();
			int fastRes = fast(s);
			int slowRes = slowMethod(s);
			if (fastRes != slowRes) {
				System.err.println("Mismatch on: " + s);
				System.err.println("Fast: " + fastRes);
				System.err.println("Slow: " + slowRes);
				throw new AssertionError();
			}
			System.err.println("Iteration: " + t);
		}
	}

	C() throws IOException {
		bufReader = new BufferedReader(new InputStreamReader(System.in));
		printWriter = new PrintWriter(System.out);
		execute();
		// run();
		printWriter.close();
	}

	public static void main(String[] args) throws IOException {
		new C();
	}

	String next() {
		while (tokenStream == null || !tokenStream.hasMoreTokens()) {
			try {
				tokenStream = new StringTokenizer(bufReader.readLine());
			} catch (Exception e) {
				eofFlag = true;
				return null;
			}
		}
		return tokenStream.nextToken();
	}

	String readLine() {
		try {
			return bufReader.readLine();
		} catch (IOException e) {
			eofFlag = true;
			return null;
		}
	}

	int nextInt() throws IOException {
		return Integer.parseInt(next());
	}

	long nextLong() throws IOException {
		return Long.parseLong(next());
	}

	double nextDouble() throws IOException {
		return Double.parseDouble(next());
	}
}
